import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"AI App 路由与页面","description":"","frontmatter":{"title":"AI App 路由与页面"},"headers":[],"relativePath":"ai/app/routing.md","filePath":"ai/app/routing.md","lastUpdated":1786936077000}'),a={name:"ai/app/routing.md"};function r(i,e,n,l,s,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="ai-app-路由与页面" tabindex="-1">AI App 路由与页面 <a class="header-anchor" href="#ai-app-路由与页面" aria-label="Permalink to &quot;AI App 路由与页面&quot;">​</a></h1><blockquote><p><code>ai/app/src/router.ts</code> 完整路由表与守卫逻辑（<code>createAiRouter</code>）。</p></blockquote><h2 id="一、路由总览" tabindex="-1">一、路由总览 <a class="header-anchor" href="#一、路由总览" aria-label="Permalink to &quot;一、路由总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>名称</th><th>视图</th><th>说明</th></tr></thead><tbody><tr><td><code>/login</code></td><td><code>login</code></td><td>platform-shared <code>LoginView</code></td><td>登录页（<code>meta.public</code>），独立模式自动跳转已登录用户</td></tr><tr><td><code>/auth/callback</code></td><td><code>auth-callback</code></td><td><code>AuthCallbackView</code></td><td>SSO/OAuth 回调（<code>meta.public</code>）</td></tr><tr><td><code>/shared/:shareId</code></td><td><code>shared-conversation</code></td><td><code>SharedConversationView</code></td><td>分享对话只读查看（<code>meta.public</code>）</td></tr></tbody></table><p>以下均为 <code>AiLayout</code>（侧栏 + 主内容）子路由：</p><table tabindex="0"><thead><tr><th>路径</th><th>名称</th><th>视图</th></tr></thead><tbody><tr><td><code>/</code></td><td><code>chat</code></td><td><code>AiChatView</code></td></tr><tr><td><code>/rag</code></td><td><code>rag</code></td><td><code>RagKnowledgeBase</code></td></tr><tr><td><code>/memory</code></td><td><code>memory</code></td><td><code>MemoryManagementView</code></td></tr><tr><td><code>/integration</code></td><td><code>integration</code></td><td><code>WorkflowIntegrationView</code></td></tr><tr><td><code>/monitor</code></td><td><code>monitor</code></td><td><code>AiMonitorView</code></td></tr><tr><td><code>/plugins</code></td><td><code>plugin-center</code></td><td><code>PluginCenterView</code></td></tr><tr><td><code>/mcp</code></td><td><code>mcp-manager</code></td><td><code>McpManagerView</code></td></tr><tr><td><code>/workflows</code></td><td><code>agent-workflows</code></td><td><code>AgentWorkflowListView</code></td></tr><tr><td><code>/executions</code></td><td><code>agent-executions</code></td><td><code>AgentExecutionListView</code></td></tr><tr><td><code>/workflows/:id/executions</code></td><td><code>agent-workflow-executions</code></td><td><code>AgentExecutionListView</code></td></tr><tr><td><code>/settings/keys</code></td><td><code>api-keys</code></td><td><code>ApiKeyManagerView</code></td></tr><tr><td><code>/settings/models</code></td><td><code>model-settings</code></td><td><code>ModelSettingsView</code></td></tr><tr><td><code>/settings/embedding</code></td><td><code>embedding-settings</code></td><td><code>EmbeddingSettingsView</code></td></tr><tr><td><code>/settings/templates</code></td><td><code>workflow-templates</code></td><td><code>WorkflowTemplateManagerView</code></td></tr><tr><td><code>/debug/routing</code></td><td><code>routing-debug</code></td><td><code>RoutingDebugView</code></td></tr><tr><td><code>/debug/workflow/:id</code></td><td><code>workflow-debug</code></td><td><code>WorkflowDebugView</code></td></tr><tr><td><code>/debug/harness</code></td><td><code>harness-debug</code></td><td><code>HarnessTraceView</code></td></tr><tr><td><code>/debug/rag</code></td><td><code>rag-debug</code></td><td><code>RagDebugView</code></td></tr><tr><td><code>/evaluation</code></td><td><code>evaluation</code></td><td><code>EvaluationView</code></td></tr><tr><td><code>/schedules</code></td><td><code>schedules</code></td><td><code>ScheduleView</code></td></tr></tbody></table><p>全屏页面（脱离 AiLayout 侧栏，自带顶栏工具条）：</p><table tabindex="0"><thead><tr><th>路径</th><th>名称</th><th>视图</th></tr></thead><tbody><tr><td><code>/workflows/:id</code></td><td><code>agent-workflow-designer</code></td><td><code>AgentWorkflowDesignerView</code></td></tr><tr><td><code>/executions/:id</code></td><td><code>agent-execution-detail</code></td><td><code>AgentExecutionDetailView</code></td></tr><tr><td><code>/sidebar</code></td><td><code>sidebar</code></td><td><code>AiSidebarView</code></td></tr></tbody></table><h2 id="二、守卫与公开路由" tabindex="-1">二、守卫与公开路由 <a class="header-anchor" href="#二、守卫与公开路由" aria-label="Permalink to &quot;二、守卫与公开路由&quot;">​</a></h2><p><code>router.beforeEach</code>：</p><ul><li><code>meta.public</code> 路由（<code>login</code> / <code>auth-callback</code> / <code>shared/:shareId</code>）跳过鉴权；<code>login</code> 在独立模式（非 qiankun）下若已登录，经 <code>resolvePostLoginNavigation</code> 跳转到 <code>redirect</code> 目标</li><li>其余路由经 <code>guardAuthenticatedRoute</code>（platform-shared <code>authSession</code>）校验 token，未登录跳转登录页</li></ul><h2 id="三、route-base-推断-resolveroutebase" tabindex="-1">三、Route Base 推断（<code>resolveRouteBase</code>） <a class="header-anchor" href="#三、route-base-推断-resolveroutebase" aria-label="Permalink to &quot;三、Route Base 推断（`resolveRouteBase`）&quot;">​</a></h2><p>优先级从高到低：</p><ol><li>外部传入的 <code>routeBase</code>（qiankun mount 时 <code>props.getRouteBase()</code>；<code>mode === &#39;sidebar&#39;</code> 时为 <code>/sidebar</code>）</li><li>从 <code>window.location.pathname</code> 推断 qiankun 容器前缀（匹配 <code>/schema-platform/app/ai/...</code> 或 <code>/schema-platform/standalone/ai/...</code>）</li><li><code>VITE_ROUTE_BASE</code>（独立部署时与 nginx 路径一致，避免与 BASE_URL 重复拼接）</li><li><code>import.meta.env.BASE_URL</code></li><li>默认 <code>/</code></li></ol><h2 id="四、导航高亮规则" tabindex="-1">四、导航高亮规则 <a class="header-anchor" href="#四、导航高亮规则" aria-label="Permalink to &quot;四、导航高亮规则&quot;">​</a></h2><p><code>/workflows*</code> 与 <code>/executions*</code> 均激活侧栏「Agent 编排」项（见 <a href="./../design/overview.html">设计概览</a> 的 <code>activeNav</code> 规则）。</p><h2 id="五、相关文档" tabindex="-1">五、相关文档 <a class="header-anchor" href="#五、相关文档" aria-label="Permalink to &quot;五、相关文档&quot;">​</a></h2><ul><li><a href="./index.html">App 概览</a> — 功能与嵌入模式</li><li><a href="./architecture.html">架构与分层</a> — 目录结构与各层清单</li><li><a href="./../design/overview.html">设计概览</a> — 信息架构与导航线框</li></ul>',18)])])}const p=d(a,[["render",r]]);export{g as __pageData,p as default};
